values ('education-support', 'Education Support', 'School fees, uniforms, books and back-to-school packs so children stay in class.', 'Too many bright children leave school because a family cannot pay fees or buy a uniform. We cover what keeps them in class, and we stay in touch with their schools through the year.', '"students-window"'::jsonb, array['School fees and exam fees', 'Uniforms, sandals and school bags', 'Textbooks and writing materials', 'Back-to-school packs each September']::text[], '[{"title":"We meet the family","body":"Local leaders and teachers tell us which children are at risk of dropping out."},{"title":"We pay the school directly","body":"Fees go to the school, and supplies go into the child''s hands."},{"title":"We follow up","body":"We check in with the school each term to see how the child is doing."}]'::jsonb, '{"value":"2,400+","label":"children kept in school"}'::jsonb, '["classroom-smiles","students-reading","classroom-lesson","pupils-studying","boy-uniform"]'::jsonb, 0);

values ('women-and-widows-livelihoods', 'Women & Widows Livelihoods', 'Skills training and small business grants that give mothers a steady income.', 'When a mother earns, the whole household is steadier. We train women and widows in a trade, give them a grant or starter kit, and mentor them while the business finds its feet.', '"sewing-lagos"'::jsonb, array['Tailoring, catering, hairdressing and soap making', 'Business and bookkeeping basics', 'Grants and starter kits for graduates', 'Six months of follow-up mentoring']::text[], '[{"title":"Train","body":"Hands-on classes with local tradespeople, usually over eight weeks."},{"title":"Equip","body":"Graduates receive a grant or the tools to start trading straight away."},{"title":"Mentor","body":"We visit and advise until the business is earning on its own."}]'::jsonb, '{"value":"650","label":"women supported with grants"}'::jsonb, '["sewing-lagos","tailor-workshop","women-gathering","food-women"]'::jsonb, 1);

values ('youth-skills', 'Youth Skills & Digital Training', 'Vocational and computer training, with starter kits for graduates.', 'Young people need a skill they can earn from. Our classes cover computer basics, digital work and practical trades, and end with a starter kit or a work placement.', '"laptop-learning"'::jsonb, array['Computer literacy and digital skills', 'Practical trades and apprenticeships', 'CV writing and interview practice', 'Starter kits and placements for graduates']::text[], '[{"title":"Learn","body":"Small classes, taught by people who do the work every day."},{"title":"Practise","body":"Real projects and apprenticeships with local businesses."},{"title":"Launch","body":"Graduates leave with a kit, a placement or their first clients."}]'::jsonb, '{"value":"300+","label":"young people trained"}'::jsonb, '["laptop-learning","computer-class","computer-teacher","lab-teacher"]'::jsonb, 2);

values ('community-health', 'Community Health Outreach', 'Free checks, screenings and medicines, taken to the people who need them.', 'Many families live hours from a clinic. Our volunteer doctors and nurses hold free health days in their communities, with screening, treatment and referrals.', '"medical-outreach"'::jsonb, array['Blood pressure, sugar and eye checks', 'Free basic medicines', 'Health talks for mothers and carers', 'Referrals for follow-up care']::text[], '[{"title":"Plan with the community","body":"We agree a date and place with local leaders and health workers."},{"title":"Screen and treat","body":"Volunteer clinicians see patients from morning till dusk."},{"title":"Refer","body":"Anyone who needs more care is referred and supported to get it."}]'::jsonb, '{"value":"5,000+","label":"people screened"}'::jsonb, '["medical-outreach","health-check","health-gombe","health-rural","health-children","clinic-check"]'::jsonb, 3);

values ('food-and-welfare', 'Food & Welfare Relief', 'Food items, clothing and festive outreaches for families going through hard seasons.', 'Hard seasons come to every family. We distribute food, clothing and essentials to households that need a hand, and hold festive outreaches so no family is left out.', '"relief-supplies"'::jsonb, array['Food packs for households in need', 'Clothing and essentials', 'Christmas and Sallah outreaches', 'Emergency support after floods and fires']::text[], '[{"title":"Identify","body":"Community leaders help us reach the households in greatest need."},{"title":"Distribute","body":"Volunteers pack and hand out supplies on the day."},{"title":"Stay close","body":"Families who need longer support are linked to our other programmes."}]'::jsonb, '{"value":"1,800","label":"food packs given"}'::jsonb, '["relief-supplies","food-women","volunteer-children","volunteer-carrying"]'::jsonb, 4);

values ('clean-water', 'Clean Water & Community Projects', 'Boreholes and sanitation projects that save hours of walking every day.', 'Clean water close to home changes everything: children get to school on time and families fall sick less often. We build and maintain boreholes with the communities that use them.', '"water-pump"'::jsonb, array['Hand-pump and solar boreholes', 'Water point maintenance', 'Hygiene and sanitation teaching', 'Small community repairs']::text[], '[{"title":"Survey","body":"We test the site and agree ownership with the community."},{"title":"Build","body":"Local contractors drill and install the borehole."},{"title":"Maintain","body":"A trained water committee looks after it, with our support."}]'::jsonb, '{"value":"9","label":"boreholes built"}'::jsonb, '["water-pump","kids-pump","child-well","hands-water"]'::jsonb, 5);

values ('back-to-school-packs', 'Back-to-school packs for 300 pupils', 'Bags, books, sandals and uniforms went home with every pupil at our September outreach.', 'On the first Saturday of September, the school hall filled up early. Parents queued with their children, many of whom had not been sure they would return to class this term.

Volunteers handed out 300 packs, each with a school bag, exercise books, a mathematical set, sandals and a uniform measured to size the week before.

For 41 of the pupils, we also paid the term''s fees directly to the school. Their head teacher told us that last year, a third of that class did not come back after the holidays.

We will visit again at mid-term to see how every child is getting on.', '"students-reading"'::jsonb, '["classroom-lesson","pupils-studying"]'::jsonb, 'education-support', true, '2026-10-20T00:00:00.000Z');

values ('free-health-screening', 'A free health screening day for 500 residents', 'Volunteer doctors and nurses checked blood pressure, sugar levels and eyesight from morning till dusk.', 'Twelve volunteer doctors, nurses and pharmacists set up in the community hall at 8am. By noon, the queue stretched past the market.

Over the day, 500 residents had their blood pressure, blood sugar and eyesight checked. Many had never been screened before.

Sixty-three people were found with high blood pressure, and 18 were referred for follow-up care, which the foundation is supporting.', '"health-gombe"'::jsonb, '["health-rural","clinic-check"]'::jsonb, 'community-health', true, '2026-10-01T00:00:00.000Z');

values ('first-borehole', 'Clean water, a short walk from home', 'A new borehole now serves families who used to walk an hour each way for water.', 'Before this year, families in the settlement walked an hour each way to the nearest reliable water point, often before school.

The new hand-pump borehole was drilled in six days by a local contractor. A water committee of five residents has been trained to look after it.

The head teacher says morning attendance has already improved.', '"kids-pump"'::jsonb, '["child-well","hands-water"]'::jsonb, 'clean-water', true, '2026-09-12T00:00:00.000Z');

values ('sixty-women-graduate', 'Sixty women graduate from skills training', 'After eight weeks of classes, every graduate left with a grant or a starter kit for her trade.', 'The graduation started with a song and ended with sixty women carrying sewing machines, ovens and hair dryers home.

Over eight weeks, they learned tailoring, catering or hairdressing from local tradespeople, plus the basics of keeping accounts.

Our team will visit each of them over the next six months as their businesses get going.', '"tailor-workshop"'::jsonb, '["sewing-lagos","women-gathering"]'::jsonb, 'women-and-widows-livelihoods', true, '2026-08-24T00:00:00.000Z');

values ('youth-digital-bootcamp', 'A digital skills bootcamp for young people', 'Forty young people spent a month learning computer skills, and twelve have already found paid work.', 'For four weeks, forty young people met every weekday to learn computer basics, design and online work.

Volunteer instructors set real projects for local businesses, so every student finished with work to show.

Twelve graduates have since found paid work, and the rest are on placements with our partners.', '"computer-class"'::jsonb, '["computer-teacher","lab-teacher"]'::jsonb, 'youth-skills', true, '2026-08-05T00:00:00.000Z');

values ('christmas-food-outreach', 'A Christmas outreach for 400 families', 'Rice, oil, beans and a little something for the children, for every family on the list.', 'In the week before Christmas, volunteers packed 400 food parcels with rice, beans, oil, tomatoes and seasoning.

Every family also took home a small gift for each child, donated by supporters in Lagos.

We are grateful to everyone who gave, packed, drove and served to make the day possible.', '"food-women"'::jsonb, '["relief-supplies","volunteer-children"]'::jsonb, 'food-and-welfare', true, '2026-07-17T00:00:00.000Z');

